import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

test('initial state and unknown ids', async () => {
  const h = await createHost();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 0, votedFor: null });
  assert.equal(await h.node('n9'), null);
  assert.equal((await h.timeout('n9')).ok, false);
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout starts an election, messages carry the brief data', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0' });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'n0');
    assert.equal(m.action, 'RequestVote');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.deepEqual(msgs.map((m) => m.to).sort(), ['n1', 'n2']);
  assert.equal((await h.timeout('n0')).ok, false);
  const one = msgs.find((m) => m.to === 'n1')!;
  await h.deliver(one.id);
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0' });
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  assert.deepEqual(reply, { ...reply, from: 'n1', to: 'n0', data: { term: 1, granted: true } });
  assert.equal((await h.timeout('n1')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0' });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n0' });
});

test('split vote: all three time out, nobody leads', async () => {
  const h = await createHost();
  for (const n of ['n0', 'n1', 'n2']) assert.deepEqual(await h.timeout(n), { ok: true });
  await h.deliverAll();
  for (const n of ['n0', 'n1', 'n2']) assert.deepEqual(await h.node(n), { role: 'candidate', term: 1, votedFor: n });
});

test('two candidates: exactly one leader', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  await h.deliverAll();
  const views = await Promise.all(['n0', 'n1', 'n2'].map((n) => h.node(n)));
  assert.equal(views.filter((v) => v!.role === 'leader').length, 1);
});

