import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const NODES = ['n0', 'n1', 'n2'];

test('initial state and unknown ids', async () => {
  const h = await createHost();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 0, votedFor: null, leader: null });
  assert.equal(await h.node('n9'), null);
  assert.equal((await h.timeout('n9')).ok, false);
  assert.deepEqual(await h.inFlight(), []);
});

test('timeout starts an election, messages carry the brief data', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'candidate', term: 1, votedFor: 'n0', leader: null });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  for (const m of msgs) {
    assert.equal(m.from, 'n0');
    assert.equal(m.action, 'RequestVote');
    assert.deepEqual(m.data, { from: 'n0', term: 1 });
  }
  assert.deepEqual(msgs.map((m) => m.to).sort(), ['n1', 'n2']);
  assert.equal((await h.timeout('n0')).ok, false);
  await h.deliver(msgs.find((m) => m.to === 'n1')!.id);
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  assert.deepEqual(reply, { ...reply, from: 'n1', to: 'n0', data: { term: 1, granted: true } });
  assert.equal((await h.timeout('n1')).ok, false);
  await h.deliver(reply.id);
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  const leaders = (await h.inFlight()).filter((m) => m.action === 'Leader');
  assert.deepEqual(leaders.map((m) => m.to).sort(), ['n1', 'n2']);
  for (const m of leaders) assert.deepEqual(m.data, { from: 'n0', term: 1 });
  // n2 hears the announcement before the RequestVote: term 1 without voting.
  await h.deliver(leaders.find((m) => m.to === 'n2')!.id);
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  await h.deliverAll();
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
});

test('split vote: all three time out, nobody leads', async () => {
  const h = await createHost();
  for (const n of NODES) assert.deepEqual(await h.timeout(n), { ok: true });
  await h.deliverAll();
  for (const n of NODES) assert.deepEqual(await h.node(n), { role: 'candidate', term: 1, votedFor: n, leader: null });
});

test('two candidates: one leader, the other steps down keeping its vote', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  await h.deliverAll();
  const views = await Promise.all(NODES.map((n) => h.node(n)));
  const leaders = views.filter((v) => v!.role === 'leader');
  assert.equal(leaders.length, 1);
  const leader = leaders[0]!.votedFor;
  for (const [i, v] of views.entries()) {
    assert.equal(v!.leader, leader);
    if (NODES[i] !== leader) assert.equal(v!.role, 'follower');
  }
  const loser = leader === 'n0' ? 'n1' : 'n0';
  assert.equal((await h.node(loser))!.votedFor, loser);
});

