test('giveUp: refused unless candidate; the candidate keeps its vote and ignores replies', async () => {
  const h = await createHost();
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.giveUp('n9')).ok, false);
  await h.timeout('n0');
  assert.deepEqual(await h.giveUp('n0'), { ok: true });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.timeout('n0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  assert.equal((await h.inFlight()).length, 0);
  // n1 runs, and n0 does not vote for it: n2 alone gives n1 its majority.
  await h.timeout('n1');
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
});

